import { acceptJobOffer, acceptSponsorOffer, addNews, advanceMinute, advanceSeason, autoSelectLineup, completeRound, createCareer, createLiveMatch, getClub, getManagedClub, getNextFixture, getStartingLineup, getStandings, makeSubstitution, migrateCareer, money, playerPositionLabel, restManagedSquad, resumeMatch, setCareerDifficulty, setCareerPace, setStartingPlayer, simulateNextFixtureFast, toggleCareerInvestors, type Career, type Club, type Fixture, type MatchState, type Player, type Screen, type Tactic } from "./engine";
